INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('2dcdbf1a-7310-5675-ad95-78c91601f4be','Tornozelo para cima e para baixo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/mobilidade.png',NULL,'{"posicao_inicial": ["Sentado ou deitado, apoie a perna e o calcanhar confortavelmente, deixando o pé livre para mexer."], "execucao": ["Mova lentamente o pé para cima e para baixo, sem forçar.", "Uma subida e descida completas contam como uma repetição."], "pontos_chave": ["Não desenhe movimentos amplos para dentro nem force a ponta do pé.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Sentado ou deitado, apoie a perna e o calcanhar confortavelmente, deixando o pé livre para mexer.

execucao
• Mova lentamente o pé para cima e para baixo, sem forçar.
• Uma subida e descida completas contam como uma repetição.

pontos chave
• Não desenhe movimentos amplos para dentro nem force a ponta do pé.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Mobilidade / Alongamento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('78f8f906-2cbb-59f0-b356-489994340764','Calcanhares e pontas dos pés sentado',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/sentado.png',NULL,'{"posicao_inicial": ["Sente-se numa cadeira firme, joelhos dobrados e pés apoiados."], "execucao": ["Levante os calcanhares mantendo a parte da frente dos pés no chão e volte a apoiar.", "Depois levante as pontas dos pés mantendo os calcanhares apoiados. O ciclo conta como uma repetição."], "pontos_chave": ["Sem carga adicional e numa amplitude confortável.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Sente-se numa cadeira firme, joelhos dobrados e pés apoiados.

execucao
• Levante os calcanhares mantendo a parte da frente dos pés no chão e volte a apoiar.
• Depois levante as pontas dos pés mantendo os calcanhares apoiados. O ciclo conta como uma repetição.

pontos chave
• Sem carga adicional e numa amplitude confortável.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Mobilidade / Alongamento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('0137e01f-ecdd-5df6-b645-98cc49f3e8f3','Pressão suave do pé para fora — isométrico',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/isometrico.png',NULL,'{"posicao_inicial": ["Sentado, pé apoiado e orientado à frente. Encoste a parte externa da frente do pé a um apoio acolchoado, fixo e estável, colocado conforme ensinado."], "execucao": ["Pressione suavemente para fora, sem deixar o pé ou a perna mexer.", "Mantenha durante o tempo prescrito e relaxe."], "pontos_chave": ["Não use um objeto solto que possa deslizar. A pressão não deve provocar dor aguda ou fricção na pele.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Sentado, pé apoiado e orientado à frente. Encoste a parte externa da frente do pé a um apoio acolchoado, fixo e estável, colocado conforme ensinado.

execucao
• Pressione suavemente para fora, sem deixar o pé ou a perna mexer.
• Mantenha durante o tempo prescrito e relaxe.

pontos chave
• Não use um objeto solto que possa deslizar. A pressão não deve provocar dor aguda ou fricção na pele.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('1da52705-c100-506a-817a-6812ae9a670e','Transferência de peso com apoio — tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/transferencia-peso.png',NULL,'{"posicao_inicial": ["De pé diante de uma bancada firme, mãos apoiadas e ambos os pés no chão."], "execucao": ["Transfira ligeiramente o peso entre os dois pés, aproximando-o do lado lesionado apenas dentro do apoio autorizado.", "Regresse à distribuição inicial."], "pontos_chave": ["Não levantar o outro pé nem inclinar o tornozelo. Não fazer se não estiver autorizado a apoiar.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé diante de uma bancada firme, mãos apoiadas e ambos os pés no chão.

execucao
• Transfira ligeiramente o peso entre os dois pés, aproximando-o do lado lesionado apenas dentro do apoio autorizado.
• Regresse à distribuição inicial.

pontos chave
• Não levantar o outro pé nem inclinar o tornozelo. Não fazer se não estiver autorizado a apoiar.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('c41588d5-3490-5ed1-a29a-8629873dec71','Marcha em plano — recuperação do tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/gonartrose/2026-10-28/marcha-curta.png',NULL,'{"posicao_inicial": ["Use piso plano, livre de obstáculos, calçado estável e os auxiliares prescritos."], "execucao": ["Caminhe devagar, com passos curtos e controlados. Use canadianas se prescritas.", "Pare para descansar antes de aumentar a claudicação."], "pontos_chave": ["A imagem mostra a variante sem canadianas; use-as se indicadas.", "Só progrida tempo ou ritmo após tolerar a dose atual. Não é corrida.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Use piso plano, livre de obstáculos, calçado estável e os auxiliares prescritos.

execucao
• Caminhe devagar, com passos curtos e controlados. Use canadianas se prescritas.
• Pare para descansar antes de aumentar a claudicação.

pontos chave
• A imagem mostra a variante sem canadianas; use-as se indicadas.
• Só progrida tempo ou ritmo após tolerar a dose atual. Não é corrida.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Cardiovascular']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('0196d42b-7e6d-5dc4-9a34-6d055664925c','Ponte glútea — recuperação do tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/ponte-bilateral.png',NULL,'{"posicao_inicial": ["Deitado de costas, cabeça apoiada, joelhos dobrados e pés numa largura confortável."], "execucao": ["Eleve ligeiramente a bacia e volte a pousar devagar."], "pontos_chave": ["Faça apenas se o apoio dos pés for autorizado e confortável. Não compense arqueando a lombar.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Deitado de costas, cabeça apoiada, joelhos dobrados e pés numa largura confortável.

execucao
• Eleve ligeiramente a bacia e volte a pousar devagar.

pontos chave
• Faça apenas se o apoio dos pés for autorizado e confortável. Não compense arqueando a lombar.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('06ecd5c5-8e5d-5363-8d27-cf1b8ee81f30','Pé para cima com elástico — dorsiflexão',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/dorsiflexao.png',NULL,'{"posicao_inicial": ["Sentado, perna e calcanhar apoiados, pé livre. Elástico à volta da frente do pé, preso num ponto fixo à sua frente, conforme ensinado."], "execucao": ["Puxe a ponta do pé na sua direção, contra o elástico.", "Regresse lentamente, sem deixar o elástico puxar de forma brusca."], "pontos_chave": ["Fixação segura, elástico íntegro e resistência ligeira. Não prenda a objetos soltos.", "O elástico puxa para a frente, não é segurado nas mãos; não rodar o joelho.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Sentado, perna e calcanhar apoiados, pé livre. Elástico à volta da frente do pé, preso num ponto fixo à sua frente, conforme ensinado.

execucao
• Puxe a ponta do pé na sua direção, contra o elástico.
• Regresse lentamente, sem deixar o elástico puxar de forma brusca.

pontos chave
• Fixação segura, elástico íntegro e resistência ligeira. Não prenda a objetos soltos.
• O elástico puxa para a frente, não é segurado nas mãos; não rodar o joelho.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('8ee1fffd-45c5-543c-8532-d9dc287d0365','Pé para fora com elástico — eversão',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/eversao.png',NULL,'{"posicao_inicial": ["Sentado, joelhos dobrados, calcanhares apoiados e elástico leve em laço à volta da frente dos dois pés, conforme ensinado."], "execucao": ["Mantenha o pé não exercitado estável. Mova a frente do outro pé ligeiramente para fora contra o elástico.", "Regresse lentamente à posição inicial."], "pontos_chave": ["Mantenha o calcanhar e o joelho controlados, sem rodar toda a perna. Não force inversão no regresso.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Sentado, joelhos dobrados, calcanhares apoiados e elástico leve em laço à volta da frente dos dois pés, conforme ensinado.

execucao
• Mantenha o pé não exercitado estável. Mova a frente do outro pé ligeiramente para fora contra o elástico.
• Regresse lentamente à posição inicial.

pontos chave
• Mantenha o calcanhar e o joelho controlados, sem rodar toda a perna. Não force inversão no regresso.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('0973ca2d-842b-59c6-9d90-3277ba757a54','Elevação dos calcanhares com apoio — tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/gonartrose/2026-10-28/calcanhares.png',NULL,'{"posicao_inicial": ["De pé no chão, diante de bancada firme, mãos apoiadas e pés paralelos."], "execucao": ["Eleve os dois calcanhares e volte a pousá-los devagar."], "pontos_chave": ["Não balance o corpo nem deixe o tornozelo ceder para fora.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé no chão, diante de bancada firme, mãos apoiadas e pés paralelos.

execucao
• Eleve os dois calcanhares e volte a pousá-los devagar.

pontos chave
• Não balance o corpo nem deixe o tornozelo ceder para fora.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('f1dfde4b-79f7-5cd0-8153-f415e3fcbeef','Joelho à parede — mobilidade do tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/parede.png',NULL,'{"posicao_inicial": ["De pé diante de uma parede, mãos apoiadas e um pé perto da parede, com calcanhar no chão."], "execucao": ["Aproxime suavemente o joelho da parede, mantendo-o orientado sobre o pé.", "Regresse. Não é necessário tocar na parede se isso exigir forçar."], "pontos_chave": ["Aproxime mais o pé da parede se necessário. Não levantar o calcanhar nem insistir numa dor de bloqueio.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé diante de uma parede, mãos apoiadas e um pé perto da parede, com calcanhar no chão.

execucao
• Aproxime suavemente o joelho da parede, mantendo-o orientado sobre o pé.
• Regresse. Não é necessário tocar na parede se isso exigir forçar.

pontos chave
• Aproxime mais o pé da parede se necessário. Não levantar o calcanhar nem insistir numa dor de bloqueio.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Mobilidade / Alongamento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('66ea09b0-ae9b-5e69-b34d-bae341f1bbfb','Equilíbrio numa perna com apoio — tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/apoio-unipodal.png',NULL,'{"posicao_inicial": ["De pé junto de uma bancada firme, apoie as mãos conforme necessário."], "execucao": ["Transfira o apoio para a perna selecionada e levante ligeiramente o outro pé.", "Mantenha o tempo prescrito, com tornozelo e joelho controlados."], "pontos_chave": ["Olhos abertos e piso firme. Pode manter contacto das mãos; não é uma prova sem apoio.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé junto de uma bancada firme, apoie as mãos conforme necessário.

execucao
• Transfira o apoio para a perna selecionada e levante ligeiramente o outro pé.
• Mantenha o tempo prescrito, com tornozelo e joelho controlados.

pontos chave
• Olhos abertos e piso firme. Pode manter contacto das mãos; não é uma prova sem apoio.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('05b8122d-a8b1-5afc-ac75-1b272a6dfcda','Sentar e levantar — recuperação do tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/sentar-levantar.png',NULL,'{"posicao_inicial": ["Cadeira firme, altura adaptada, pés apoiados e separados numa largura confortável."], "execucao": ["Levante-se e sente-se devagar, usando os braços se necessário."], "pontos_chave": ["Mantenha os pés apoiados. Use cadeira mais alta se o tornozelo não tolerar maior flexão.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Cadeira firme, altura adaptada, pés apoiados e separados numa largura confortável.

execucao
• Levante-se e sente-se devagar, usando os braços se necessário.

pontos chave
• Mantenha os pés apoiados. Use cadeira mais alta se o tornozelo não tolerar maior flexão.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
