INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('ef3b2232-96dc-5c82-a799-58c4d74ff137','Subir e descer um degrau baixo com apoio — tornozelo',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/step-up.png',NULL,'{"posicao_inicial": ["Junto de corrimão ou bancada firme, use um degrau baixo e estável."], "execucao": ["Suba com o pé selecionado, controlando o tornozelo e o joelho.", "Regresse devagar à posição inicial, com o apoio necessário. Subir e regressar contam como uma repetição."], "pontos_chave": ["Não saltar nem aumentar a altura antes de controlar a versão baixa.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• Junto de corrimão ou bancada firme, use um degrau baixo e estável.

execucao
• Suba com o pé selecionado, controlando o tornozelo e o joelho.
• Regresse devagar à posição inicial, com o apoio necessário. Subir e regressar contam como uma repetição.

pontos chave
• Não saltar nem aumentar a altura antes de controlar a versão baixa.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('0021c09b-c515-5586-8068-e0a119977125','Inclinação à frente numa perna com apoio',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/inclinacao.png',NULL,'{"posicao_inicial": ["De pé junto de bancada firme, uma mão apoiada, peso na perna selecionada e joelho ligeiramente dobrado."], "execucao": ["Incline ligeiramente o tronco pela anca, levando a outra perna um pouco para trás.", "Regresse com controlo."], "pontos_chave": ["Amplitude curta, sem peso adicional. Mantenha o pé de apoio estável; não é necessário baixar o tronco até ficar horizontal.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé junto de bancada firme, uma mão apoiada, peso na perna selecionada e joelho ligeiramente dobrado.

execucao
• Incline ligeiramente o tronco pela anca, levando a outra perna um pouco para trás.
• Regresse com controlo.

pontos chave
• Amplitude curta, sem peso adicional. Mantenha o pé de apoio estável; não é necessário baixar o tronco até ficar horizontal.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('1e61202e-380d-54a9-b35c-101562acf0a0','Toques em três direções com apoio',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/toques.png',NULL,'{"posicao_inicial": ["De pé junto de uma bancada firme, mão apoiada e peso na perna selecionada."], "execucao": ["Toque ligeiramente com o outro pé à frente, ao lado e atrás, regressando ao centro entre toques.", "Os três toques e regressos contam como um ciclo."], "pontos_chave": ["Alcances curtos, sem saltos. A perna de apoio permanece controlada e o pé de toque não sustenta o peso principal.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé junto de uma bancada firme, mão apoiada e peso na perna selecionada.

execucao
• Toque ligeiramente com o outro pé à frente, ao lado e atrás, regressando ao centro entre toques.
• Os três toques e regressos contam como um ciclo.

pontos chave
• Alcances curtos, sem saltos. A perna de apoio permanece controlada e o pé de toque não sustenta o peso principal.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('9ffb13b6-2346-5240-a76e-a2cdae2475e7','Passos laterais controlados junto da bancada',ARRAY['Casa','Clínica']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/entorse-tornozelo/2026-10-30/laterais.png',NULL,'{"posicao_inicial": ["De pé ao longo de bancada firme, pés numa largura confortável, mãos próximas do apoio."], "execucao": ["Dê passos curtos para um lado e depois para o outro, sem cruzar os pés."], "pontos_chave": ["Sem elástico e sem saltar. Mantenha apoio disponível e espaço livre.", "Faça apenas o lado, apoio, amplitude e dose prescritos."], "erros_comuns": ["Usar impulso, forçar dor ou continuar após perder controlo."], "dicas": ["Respire normalmente. Peça ensino da técnica antes de treinar sozinho."]}'::jsonb,'posicao inicial
• De pé ao longo de bancada firme, pés numa largura confortável, mãos próximas do apoio.

execucao
• Dê passos curtos para um lado e depois para o outro, sem cruzar os pés.

pontos chave
• Sem elástico e sem saltar. Mantenha apoio disponível e espaço livre.
• Faça apenas o lado, apoio, amplitude e dose prescritos.

erros comuns
• Usar impulso, forçar dor ou continuar após perder controlo.

dicas
• Respire normalmente. Peça ensino da técnica antes de treinar sozinho.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.protocols_catalog (id,region,name,kind,is_active,sort_order,data) VALUES ('ce429697-6bfc-594e-b2f3-61b3b79b3f23','tornozelo_pe','Entorse do Tornozelo — reabilitação domiciliária da entorse lateral','conservador',TRUE,13,'{"version": 1, "versao_clinica": "2026-10-30", "contextos": ["Casa", "Clínica"], "fontes": [{"title": "JOSPT/APTA 2021 — entorse lateral e instabilidade", "url": "https://www.orthopt.org/uploads/content_files/files/jospt.2021.0302.pdf", "doi": "10.2519/jospt.2021.0302"}, {"title": "PAASS 2021 — domínios para regresso ao desporto", "url": "https://pubmed.ncbi.nlm.nih.gov/34158354/", "doi": "10.1136/bjsports-2021-104087"}, {"title": "NHS — cuidados iniciais e sinais de alarme", "url": "https://www.nhs.uk/conditions/sprains-and-strains/"}, {"title": "NHS Chelsea and Westminster — compressão elástica", "url": "https://www.chelwest.nhs.uk/your-visit/patient-leaflets/surgery-services/ankle-sprain-discharge-advice"}], "status_revisao": "revisto_com_limites_de_evidencia_2026-10-30", "nota_clinica": "Três fases por critérios funcionais, seis opções por fase. Adultos com entorse lateral avaliada. Não é protocolo de fratura, lesão sindesmótica, cirurgia ou alta desportiva. Confirmar diagnóstico e restrições antes de prescrever.", "dose": "Sugestões iniciais práticas ajustáveis; não constituem dose ótima validada nem limiares universais de segurança."}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('27169389-f0b7-5f9c-949e-e89bb20ef689','ce429697-6bfc-594e-b2f3-61b3b79b3f23',1,'1 — Recuperar movimento e apoio','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Escolha por critérios e resposta clínica, sem semanas fixas.", "objetivos": [{"id": "o1", "label": "Movimentar o tornozelo e recuperar gradualmente a marcha."}], "permitido": ["Movimento e apoio apenas conforme autorização individual."], "contraindicacoes": ["Não ultrapassar as restrições de carga ou imobilização prescritas.", "Interromper perante dor aguda, instabilidade ou sinais de alarme."], "hep": ["Seis opções; fazer apenas a seleção e a dose prescritas."], "recomendacoes": [{"title": "O seu plano", "text": "Este plano aplica-se apenas à seleção da sua equipa. Se lhe foi prescrita uma bota, imobilização ou restrição de apoio, respeite essa indicação. Não é obrigatório executar os seis exercícios."}, {"title": "Apoio e canadianas", "text": "Caminhe em percursos curtos, com o apoio autorizado. Use as canadianas se prescritas, para caminhar com controlo. Reduza-as conforme orientação; não force o apoio se lhe tiver sido indicado não apoiar."}, {"title": "Pé elástico ou tornozeleira", "text": "Use o suporte indicado, sobretudo ao caminhar. O pé elástico pode ajudar no conforto e no inchaço, mas não protege como uma tornozeleira estabilizadora. Retire a compressão elástica simples para dormir, salvo indicação diferente. Bota e ortótese têm instruções próprias."}, {"title": "Verificar a compressão", "text": "O suporte não deve provocar formigueiro, dormência, dedos frios ou mudança de cor. Se acontecer, retire a compressão e procure orientação. Se o pé continuar frio, pálido ou azulado, procure avaliação urgente."}, {"title": "Gelo, se aliviar", "text": "Se aliviar, aplique gelo durante 10–15 minutos, com uma toalha entre o gelo e a pele. Pode repetir ao longo do dia, deixando a pele recuperar. Não aplique diretamente nem adormeça com o gelo. Pare perante ardor, dor ou mudança marcada da cor. Se tiver alterações da sensibilidade, circulação ou intolerância ao frio, confirme primeiro com a equipa."}, {"title": "Elevação e movimento", "text": "Ao descansar, eleve confortavelmente a perna com almofadas. Alterne com movimentos suaves e deslocações curtas autorizadas. Evite longos períodos imóvel ou com o pé pendente. Evite calor intenso na zona inicialmente."}, {"title": "Massagem", "text": "Nos primeiros dois a três dias, evite massajar a zona lesionada, sobretudo se muito inchada ou com nódoa negra. Mais tarde, apenas se aconselhada, faça massagem superficial e confortável, sem pressionar a zona dolorosa. Não faça massagem profunda para desfazer edema ou nódoas negras. Não massaje a barriga da perna se surgir dor ou inchaço novo nessa região."}, {"title": "Frequência e resposta", "text": "Faça a mobilidade em períodos curtos ao longo do dia. A equipa ajusta a frequência dos restantes exercícios. Pode sentir desconforto ligeiro. Pare perante dor aguda, sensação de falha ou perda de controlo. Se começar a coxear mais, reduza ou interrompa. Se a dor, o inchaço ou a marcha estiverem claramente piores na manhã seguinte, reduza a sessão seguinte e peça ajuste."}, {"title": "Quando procurar ajuda", "text": "Procure avaliação urgente perante deformidade, pé frio/pálido/azulado, dormência persistente, dor intensa ou crescente, incapacidade de apoio não avaliada, febre com vermelhidão/calor importante ou dor e inchaço novos na barriga da perna. Se tiver falta de ar ou dor no peito, ligue 112."}, {"title": "Reavaliação", "text": "Peça reavaliação se deixar de melhorar, houver bloqueio, dor acima do tornozelo ou episódios repetidos de instabilidade. Correr, saltar e mudar rapidamente de direção exigem progressão e autorização próprias; terminar este plano não autoriza o regresso ao desporto."}], "recomendacoes_clinicas": [{"title": "Âmbito e avaliação", "text": "Confirmar lado, gravidade, mecanismo, capacidade de carga, estado neurovascular, lesão associada, historial de entorse/instabilidade e comorbilidades. Ottawa orienta radiografia; não exclui lesão sindesmótica. Testes isolados negativos também não a excluem. Suspeita de fratura, lesão sindesmótica, osteocondral ou tendinosa exige plano próprio. Em crianças, adaptar após avaliação específica."}, {"title": "Proteção e carga", "text": "Suporte externo e dispositivo de marcha conforme gravidade, dor e proteção necessária. Entorse grave pode justificar imobilização curta, geralmente até dez dias, seguida de reabilitação. A prescrição individual de apoio prevalece sobre o catálogo. Não aplicar exercícios de carga a quem não está autorizado a apoiar."}, {"title": "Evidência e dose", "text": "Exercício estruturado e carga progressiva são a base. Seleção de seis opções por fase e doses são propostas práticas, não conjunto validado. Não há calendário, semáforo numérico ou intervalo obrigatório de progressão. Evitar inversão forçada e combinação flexão plantar/inversão inicialmente. Corrigir défices relevantes sem obrigar a espuma, olhos fechados ou instabilidade artificial."}, {"title": "Gelo e massagem", "text": "Crioterapia é opcional para sintomas, com benefício clínico limitado/incerto; não prometer acelerar cicatrização. Considerar integridade cutânea, sensibilidade, circulação e intolerância ao frio. Evitar massagem profunda e pressão sobre lesão/hematoma; não extrapolar evidência de terapia manual profissional para automassagem. Suspeita de trombose contraindica massagem e exige avaliação."}, {"title": "Alta desportiva separada", "text": "PAASS: dor, défices de amplitude/força/resistência/potência, confiança/prontidão, controlo sensoriomotor e desempenho específico incluindo treino completo. LSI 90%, 25 elevações de gémeos, Y-balance 4 cm e FAAM-Sport 90% não são autorizações universais. Este protocolo domiciliário não inclui progressão reativa ou alta desportiva. Considerar prevenção neuromuscular e suporte externo conforme risco e modalidade."}], "criterios_progressao": [{"id": "p1", "texto": "Apoio e marcha em melhoria, com menor claudicação e respeitando a proteção prescrita."}, {"id": "p2", "texto": "Movimento e seleção inicial tolerados, sem agravamento persistente; início de controlo em apoio conforme avaliação."}], "objetivos_serie": [], "recommendations_scope": "ce429697-6bfc-594e-b2f3-61b3b79b3f23:27169389-f0b7-5f9c-949e-e89bb20ef689", "revisao_cientifica": "2026-10-30"}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('15896074-682d-5388-8bdb-01f22a77b990','ce429697-6bfc-594e-b2f3-61b3b79b3f23',2,'2 — Recuperar força e equilíbrio','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Escolha por critérios e resposta clínica, sem semanas fixas.", "objetivos": [{"id": "o1", "label": "Melhorar a estabilidade para as tarefas diárias."}], "permitido": ["Movimento e apoio apenas conforme autorização individual."], "contraindicacoes": ["Não ultrapassar as restrições de carga ou imobilização prescritas.", "Interromper perante dor aguda, instabilidade ou sinais de alarme."], "hep": ["Seis opções; fazer apenas a seleção e a dose prescritas."], "recomendacoes": [{"title": "O seu plano", "text": "Este plano aplica-se apenas à seleção da sua equipa. Se lhe foi prescrita uma bota, imobilização ou restrição de apoio, respeite essa indicação. Não é obrigatório executar os seis exercícios."}, {"title": "Frequência", "text": "Reforço habitualmente em dias alternados. Mobilidade e equilíbrio podem ter frequência diferente, conforme prescrição. Use apoio estável e não feche os olhos para aumentar a dificuldade."}, {"title": "Suporte e sintomas", "text": "Use o suporte indicado, sobretudo ao caminhar. O pé elástico pode ajudar no conforto e no inchaço, mas não protege como uma tornozeleira estabilizadora. Retire a compressão elástica simples para dormir, salvo indicação diferente. Bota e ortótese têm instruções próprias. O suporte não deve provocar formigueiro, dormência, dedos frios ou mudança de cor. Se acontecer, retire a compressão e procure orientação. Se o pé continuar frio, pálido ou azulado, procure avaliação urgente."}, {"title": "Conforto", "text": "Pode elevar a perna ao descansar. Gelo apenas se ajudar: 10–15 minutos, protegido por toalha, sem adormecer. Confirme antes se tiver alterações de sensibilidade/circulação ou intolerância ao frio. Massagem só se aconselhada, superficial e sem pressionar a lesão; nunca perante dor/inchaço novo na barriga da perna."}, {"title": "Resposta ao exercício", "text": "Pode sentir desconforto ligeiro. Pare perante dor aguda, sensação de falha ou perda de controlo. Se começar a coxear mais, reduza ou interrompa. Se a dor, o inchaço ou a marcha estiverem claramente piores na manhã seguinte, reduza a sessão seguinte e peça ajuste."}, {"title": "Quando procurar ajuda", "text": "Procure avaliação urgente perante deformidade, pé frio/pálido/azulado, dormência persistente, dor intensa ou crescente, incapacidade de apoio não avaliada, febre com vermelhidão/calor importante ou dor e inchaço novos na barriga da perna. Se tiver falta de ar ou dor no peito, ligue 112."}, {"title": "Reavaliação", "text": "Peça reavaliação se deixar de melhorar, houver bloqueio, dor acima do tornozelo ou episódios repetidos de instabilidade. Correr, saltar e mudar rapidamente de direção exigem progressão e autorização próprias; terminar este plano não autoriza o regresso ao desporto."}], "recomendacoes_clinicas": [{"title": "Âmbito e avaliação", "text": "Confirmar lado, gravidade, mecanismo, capacidade de carga, estado neurovascular, lesão associada, historial de entorse/instabilidade e comorbilidades. Ottawa orienta radiografia; não exclui lesão sindesmótica. Testes isolados negativos também não a excluem. Suspeita de fratura, lesão sindesmótica, osteocondral ou tendinosa exige plano próprio. Em crianças, adaptar após avaliação específica."}, {"title": "Proteção e carga", "text": "Suporte externo e dispositivo de marcha conforme gravidade, dor e proteção necessária. Entorse grave pode justificar imobilização curta, geralmente até dez dias, seguida de reabilitação. A prescrição individual de apoio prevalece sobre o catálogo. Não aplicar exercícios de carga a quem não está autorizado a apoiar."}, {"title": "Evidência e dose", "text": "Exercício estruturado e carga progressiva são a base. Seleção de seis opções por fase e doses são propostas práticas, não conjunto validado. Não há calendário, semáforo numérico ou intervalo obrigatório de progressão. Evitar inversão forçada e combinação flexão plantar/inversão inicialmente. Corrigir défices relevantes sem obrigar a espuma, olhos fechados ou instabilidade artificial."}, {"title": "Gelo e massagem", "text": "Crioterapia é opcional para sintomas, com benefício clínico limitado/incerto; não prometer acelerar cicatrização. Considerar integridade cutânea, sensibilidade, circulação e intolerância ao frio. Evitar massagem profunda e pressão sobre lesão/hematoma; não extrapolar evidência de terapia manual profissional para automassagem. Suspeita de trombose contraindica massagem e exige avaliação."}, {"title": "Alta desportiva separada", "text": "PAASS: dor, défices de amplitude/força/resistência/potência, confiança/prontidão, controlo sensoriomotor e desempenho específico incluindo treino completo. LSI 90%, 25 elevações de gémeos, Y-balance 4 cm e FAAM-Sport 90% não são autorizações universais. Este protocolo domiciliário não inclui progressão reativa ou alta desportiva. Considerar prevenção neuromuscular e suporte externo conforme risco e modalidade."}], "criterios_progressao": [{"id": "p1", "texto": "Marcha habitual com bom controlo e exercícios sem sensação de falha."}, {"id": "p2", "texto": "Equilíbrio com o apoio necessário e força em melhoria, sem agravamento persistente após treino."}], "objetivos_serie": [], "recommendations_scope": "ce429697-6bfc-594e-b2f3-61b3b79b3f23:15896074-682d-5388-8bdb-01f22a77b990", "revisao_cientifica": "2026-10-30"}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('efe45348-aaea-5ee5-856d-7d2f2e045d32','ce429697-6bfc-594e-b2f3-61b3b79b3f23',3,'3 — Recuperar capacidade funcional','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Escolha por critérios e resposta clínica, sem semanas fixas.", "objetivos": [{"id": "o1", "label": "Preparar escadas, caminhadas e atividades habituais."}], "permitido": ["Movimento e apoio apenas conforme autorização individual."], "contraindicacoes": ["Não ultrapassar as restrições de carga ou imobilização prescritas.", "Interromper perante dor aguda, instabilidade ou sinais de alarme."], "hep": ["Seis opções; fazer apenas a seleção e a dose prescritas."], "recomendacoes": [{"title": "O seu plano", "text": "Este plano aplica-se apenas à seleção da sua equipa. Se lhe foi prescrita uma bota, imobilização ou restrição de apoio, respeite essa indicação. Não é obrigatório executar os seis exercícios."}, {"title": "Frequência e progressão", "text": "Reforço habitualmente em dias alternados. Aumente uma variável de cada vez: repetições, resistência, duração ou dificuldade. Mantenha o apoio necessário; não é obrigatório fechar os olhos ou usar superfícies instáveis."}, {"title": "Suporte", "text": "Use o suporte indicado, sobretudo ao caminhar. O pé elástico pode ajudar no conforto e no inchaço, mas não protege como uma tornozeleira estabilizadora. Retire a compressão elástica simples para dormir, salvo indicação diferente. Bota e ortótese têm instruções próprias. O suporte não deve provocar formigueiro, dormência, dedos frios ou mudança de cor. Se acontecer, retire a compressão e procure orientação. Se o pé continuar frio, pálido ou azulado, procure avaliação urgente."}, {"title": "Conforto", "text": "Eleve se ajudar. Gelo é opcional, 10–15 minutos com toalha, sem adormecer; confirme antes se alterações de sensibilidade/circulação ou intolerância ao frio. Evite massagem profunda; só superficial se aconselhada, nunca se houver dor/inchaço novo na barriga da perna."}, {"title": "Resposta ao exercício", "text": "Pode sentir desconforto ligeiro. Pare perante dor aguda, sensação de falha ou perda de controlo. Se começar a coxear mais, reduza ou interrompa. Se a dor, o inchaço ou a marcha estiverem claramente piores na manhã seguinte, reduza a sessão seguinte e peça ajuste."}, {"title": "Desporto", "text": "Peça reavaliação se deixar de melhorar, houver bloqueio, dor acima do tornozelo ou episódios repetidos de instabilidade. Correr, saltar e mudar rapidamente de direção exigem progressão e autorização próprias; terminar este plano não autoriza o regresso ao desporto."}, {"title": "Quando procurar ajuda", "text": "Procure avaliação urgente perante deformidade, pé frio/pálido/azulado, dormência persistente, dor intensa ou crescente, incapacidade de apoio não avaliada, febre com vermelhidão/calor importante ou dor e inchaço novos na barriga da perna. Se tiver falta de ar ou dor no peito, ligue 112."}], "recomendacoes_clinicas": [{"title": "Âmbito e avaliação", "text": "Confirmar lado, gravidade, mecanismo, capacidade de carga, estado neurovascular, lesão associada, historial de entorse/instabilidade e comorbilidades. Ottawa orienta radiografia; não exclui lesão sindesmótica. Testes isolados negativos também não a excluem. Suspeita de fratura, lesão sindesmótica, osteocondral ou tendinosa exige plano próprio. Em crianças, adaptar após avaliação específica."}, {"title": "Proteção e carga", "text": "Suporte externo e dispositivo de marcha conforme gravidade, dor e proteção necessária. Entorse grave pode justificar imobilização curta, geralmente até dez dias, seguida de reabilitação. A prescrição individual de apoio prevalece sobre o catálogo. Não aplicar exercícios de carga a quem não está autorizado a apoiar."}, {"title": "Evidência e dose", "text": "Exercício estruturado e carga progressiva são a base. Seleção de seis opções por fase e doses são propostas práticas, não conjunto validado. Não há calendário, semáforo numérico ou intervalo obrigatório de progressão. Evitar inversão forçada e combinação flexão plantar/inversão inicialmente. Corrigir défices relevantes sem obrigar a espuma, olhos fechados ou instabilidade artificial."}, {"title": "Gelo e massagem", "text": "Crioterapia é opcional para sintomas, com benefício clínico limitado/incerto; não prometer acelerar cicatrização. Considerar integridade cutânea, sensibilidade, circulação e intolerância ao frio. Evitar massagem profunda e pressão sobre lesão/hematoma; não extrapolar evidência de terapia manual profissional para automassagem. Suspeita de trombose contraindica massagem e exige avaliação."}, {"title": "Alta desportiva separada", "text": "PAASS: dor, défices de amplitude/força/resistência/potência, confiança/prontidão, controlo sensoriomotor e desempenho específico incluindo treino completo. LSI 90%, 25 elevações de gémeos, Y-balance 4 cm e FAAM-Sport 90% não são autorizações universais. Este protocolo domiciliário não inclui progressão reativa ou alta desportiva. Considerar prevenção neuromuscular e suporte externo conforme risco e modalidade."}], "criterios_progressao": [{"id": "p1", "texto": "Tarefas habituais com controlo, capacidade em melhoria e sem episódios de falha."}, {"id": "p2", "texto": "Gerir dose sem agravamento persistente; necessidade de reavaliação e plano específico antes de corrida, saltos ou desporto."}], "objetivos_serie": [], "recommendations_scope": "ce429697-6bfc-594e-b2f3-61b3b79b3f23:efe45348-aaea-5ee5-856d-7d2f2e045d32", "revisao_cientifica": "2026-10-30"}'::jsonb);
