INSERT INTO public.protocol_phase_exercises (id,phase_id,exercise_id,sort_order,context,is_optional,prescription_defaults,clinical_note) VALUES ('a50d45f1-4594-5294-b96c-b00d79bee6ca','efe45348-aaea-5ee5-856d-7d2f2e045d32','c41588d5-3490-5ed1-a29a-8629873dec71',6,'indiferente',TRUE,'{"sets": 1, "load": null, "reps_min": null, "reps_max": null, "reps_fixed": null, "series": null, "duration_sec": null, "duration_series": [{"duration_sec": 300}], "rest_set": 60, "rest_next": 60, "tempo_concentrico_s": null, "tempo_excentrico_s": null, "pausa_superior_s": 0, "pausa_inferior_s": 0}'::jsonb,'Dose inicial ajustável; confirmar lado, carga autorizada, amplitude, apoio e frequência. Fazer apenas a seleção prescrita. O tempo pode ser dividido em períodos menores. Usar canadianas/suporte se prescritos. A imagem sem auxiliares não altera essa indicação. Reduzir se piorarem a dor, o inchaço ou a marcha na manhã seguinte; parar perante dor aguda ou sensação de falha.');
